-- ============================================================
-- SEED EXT 6: Módulo 04 — Present Continuous (ex 206-300)
-- Tópicos: situações temporárias formais, tendências evolutivas,
-- planos futuros, contraste PC vs PS, TOEFL integrado avançado
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'present-continuous';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo present-continuous não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: PC para situações temporárias em contextos formais
  (cid,71,206,'gap_fill','_____ (research) team _____ (currently/operate) under _____ interim _____ leadership arrangement while _____ board _____ (conduct) its _____ search for _____ permanent _____ director — a _____ process that _____ (expect/passive) to _____ conclude within _____ the _____ next _____ quarter.','The / is currently operating / an / interim / the / conducts / its / permanent / a / is expected / conclude / the / next',NULL,'PC ''is currently operating'' = temporary arrangement; PS ''conducts'' = ongoing process.','medium'),
  (cid,71,207,'gap_fill','Despite _____ (their) _____ long-term _____ commitment to _____ (the) _____ region, _____ organization _____ (temporarily/scale back) _____ its _____ field _____ operations due to _____ deteriorating _____ security _____ conditions that _____ (make) sustained _____ deployment _____ (impractical).','their / long-term / the / region / the / is temporarily scaling back / its / field / deteriorating / security / make / sustained / impractical',NULL,'PC ''is temporarily scaling back'' for contingent, reversible operational reduction.','medium'),
  (cid,71,208,'gap_fill','_____ (the/ministry) _____ (pilot) _____ revised _____ curriculum in _____ selected _____ schools before _____ (decide) whether to _____ (implement) it nationally — _____ (the/evaluation) _____ (currently/gather) _____ (data) that _____ (inform) _____ final _____ (policy) _____ decision.','The ministry / is piloting / a / revised / selected / deciding / implement / the evaluation / is currently gathering / data / will inform / the / policy',NULL,'PC ''is piloting/gathering'' = temporary evaluation phase before policy decision.','medium'),
  (cid,71,209,'gap_fill','Several _____ donor _____ governments _____ (reassess) _____ their _____ funding _____ commitments in _____ light of _____ (the) _____ recent _____ audit _____ findings — a _____ review that _____ (likely/result) in _____ significant _____ changes to _____ how _____ resources _____ (allocate/passive).','donor / are reassessing / their / funding / in / the / recent / audit / a / will likely result / significant / resources / are allocated',NULL,'PC ''are reassessing'' = active review in progress; PS ''are allocated'' = ongoing allocation process.','hard'),
  (cid,71,210,'gap_fill','_____ (the/team) _____ (face) _____ significant _____ pressure to _____ (deliver) _____ results within _____ compressed _____ timeframe — a _____ situation that _____ (arising) from _____ decisions _____ (make/passive) before _____ current _____ leadership _____ (take over) and that _____ (complicate) _____ planning _____ considerably.','The team / is facing / significant / to / deliver / a / compressed / that / is arising / from / made / the / took over / is complicating / planning',NULL,'PC ''is facing/arising/complicating'' for compound temporary pressure situation.','hard'),
  (cid,71,211,'multiple_choice','Which sentence MOST correctly uses the present continuous for a temporary formal situation?','The institution is operating under emergency protocols while the standard procedures are being reviewed.','[''The institution operates under emergency protocols while reviewing standard procedures.'',''The institution is operating under emergency protocols while the standard procedures are being reviewed.'',''The institution operated under emergency protocols while the standard procedures were reviewed.'',''The institution will be operating under emergency protocols.'']','PC ''is operating...are being reviewed'' = both the emergency mode and the review are temporary, simultaneous.','easy'),
  (cid,71,212,'gap_fill','Funding _____ (currently/channel/passive) through _____ interim _____ trust _____ fund arrangement because _____ permanent _____ mechanism that _____ (originally/intend/passive) _____ (still/establish/passive/not) — _____ delay that _____ (frustrate) _____ donors and _____ (slow) _____ implementation considerably.','is currently being channelled / an / interim / trust / the / permanent / originally intended / is still not being established / a / is frustrating / is slowing',NULL,'PC ''is being channelled'' + ''is being established'' (passive) for temporary arrangement.','hard'),
  (cid,71,213,'gap_fill','_____ (the/programme/evaluation) _____ (examine) _____ (whether) _____ intended _____ outcomes _____ (achieve/passive) at _____ (the/scale) and _____ quality _____ (originally/envision/passive) — findings that _____ (shape) _____ decisions about _____ whether _____ to _____ (continue), _____ (modify), or _____ (terminate) it.','The programme evaluation / is examining / whether / the / intended / are being achieved / the / scale / quality / originally envisioned / will shape / decisions / continue / modify / terminate',NULL,'PC ''is examining/being achieved'' for evaluation in progress.','hard'),

  -- BLOCK 72: PC para situações de mudança e evolução
  (cid,72,214,'gap_fill','_____ global _____ energy _____ mix _____ (undergo) _____ fundamental _____ transformation as _____ renewable _____ capacity _____ (scale up) rapidly and _____ fossil _____ fuel _____ (lose) _____ their _____ dominant _____ share of _____ electricity _____ generation in _____ (a/growing) _____ number of _____ markets.','The / global / energy / is undergoing / a / as / renewable / is scaling up / fossil / fuels / are losing / their / dominant / share / electricity / an / a growing',NULL,'PC ''is undergoing/scaling up/losing'' for ongoing energy transition.','medium'),
  (cid,72,215,'gap_fill','_____ (the/role) of _____ (multilateral/institutions) _____ (shift) as _____ (the/distribution) of _____ global _____ power _____ (change) — _____ institutions _____ (not/simply/adapt) their _____ procedures but _____ (rethink) _____ (fundamental) _____ questions about _____ their _____ mandates.','The / role / multilateral institutions / is shifting / the distribution / global / changes / are not simply adapting / their / are rethinking / fundamental / their / mandates',NULL,'PC ''is shifting/are not adapting/are rethinking'' for institutional evolution.','hard'),
  (cid,72,216,'gap_fill','_____ academic _____ job _____ market _____ (transform/passive) by _____ (the) _____ dual _____ pressures of _____ (fiscal) _____ constraint and _____ (technological) _____ disruption — _____ (fewer) _____ tenure-track _____ positions _____ (create/passive) while _____ (demand) for _____ (non-standard) _____ academic _____ arrangements _____ (grow).','The / is being transformed / the / dual / fiscal / technological / fewer / tenure-track / are being created / demand / non-standard / is growing',NULL,'PC passive ''is being transformed/created'' + ''is growing'' for academic market change.','hard'),
  (cid,72,217,'gap_fill','Urban _____ populations _____ (age) rapidly in _____ high-income _____ countries, _____ (place) _____ unprecedented _____ demands on _____ housing _____ stock, _____ (transport) _____ infrastructure, and _____ care _____ services that _____ (design/not/passive) for _____ (this) _____ demographic _____ profile.','populations / are ageing / high-income / placing / unprecedented / housing / transport / care / were not designed / this / demographic',NULL,'PC ''are ageing/placing'' for demographic trend creating new demands.','medium'),
  (cid,72,218,'gap_fill','Consumer _____ (preference) _____ (shift) toward _____ (more) _____ sustainable _____ products, _____ (drive) _____ (structural) _____ changes in _____ (supply) _____ chains as _____ companies _____ (respond) to _____ signals _____ (emerge) from _____ changing _____ market _____ conditions.','preferences / are shifting / more / sustainable / driving / structural / supply / as / are responding / emerging / changing',NULL,'PC ''are shifting/driving/responding/emerging'' for consumer preference evolution.','medium'),
  (cid,72,219,'gap_fill','_____ boundaries _____ between _____ academic _____ disciplines _____ (blur) as _____ complex _____ (challenge) _____ (require) _____ integrative _____ approaches that _____ (draw) on _____ multiple _____ (domain) of _____ knowledge — a _____ (trend) that _____ (reshape) _____ research _____ institutions and _____ funding _____ (structure).','The / are blurring / complex / challenges / require / integrative / draw / domains / a / is reshaping / research / and / funding / structures',NULL,'PC ''are blurring/is reshaping'' for interdisciplinary trend.','medium'),
  (cid,72,220,'multiple_choice','Which present continuous usage BEST describes an evolving global trend?','The proportion of the workforce engaged in the gig economy is growing in most high-income countries.','[''The proportion of the workforce engaged in the gig economy grows.'',''The proportion of the workforce engaged in the gig economy grew.'',''The proportion of the workforce engaged in the gig economy is growing in most high-income countries.'',''The proportion of the workforce engaged in the gig economy will grow.'']','PC ''is growing'' = ongoing trend in progress, not a permanent state (PS) or future prediction.','easy'),
  (cid,72,221,'gap_fill','_____ (the/geopolitical) _____ landscape _____ (become) _____ increasingly _____ complex as _____ new _____ powers _____ (assert) _____ (their) _____ interests and _____ established _____ (player) _____ (adapt) — often _____ (reluctantly) — to _____ a _____ (more) _____ multipolar _____ order that _____ (challenge) _____ (post-war/assumption).','The / geopolitical / is becoming / increasingly / complex / new / are asserting / their / established / players / are adapting / reluctantly / a / more / multipolar / challenges / post-war assumptions',NULL,'PC ''is becoming/asserting/adapting/challenges'' for geopolitical evolution.','hard'),

  -- BLOCK 73: PC para planos futuros arranjados
  (cid,73,222,'gap_fill','_____ (the/delegation) _____ (depart) _____ for _____ Geneva _____ next _____ Monday and _____ (present) _____ (the) _____ revised _____ framework _____ at _____ (the) _____ working _____ group _____ session _____ scheduled for _____ Wednesday.','The / is departing / for / the / and / is presenting / the / revised / at / the / working / the / session',NULL,'PC ''is departing/presenting'' = arranged future plans with fixed schedule.','easy'),
  (cid,73,223,'gap_fill','_____ committee _____ (convene) _____ (on) _____ Thursday to _____ (review) _____ (the) _____ proposed _____ amendments and _____ (report) _____ findings to _____ (the) _____ full _____ board before _____ (the) _____ end of _____ (the) _____ fiscal _____ quarter.','The / is convening / on / review / the / proposed / reporting / its / the / full / the / end / the / fiscal',NULL,'PC ''is convening/reporting'' = scheduled institutional meetings.','easy'),
  (cid,73,224,'gap_fill','Several _____ (senior) _____ (researcher) _____ (join) _____ (the) _____ advisory _____ board next _____ (month), _____ (strengthen) _____ (the) _____ institutional _____ capacity for _____ (strategic) _____ oversight at _____ a _____ time when _____ (the) _____ organization _____ (face) _____ significant _____ transition.','senior / researchers / are joining / the / advisory / next / strengthening / the / institutional / strategic / at / the / is facing / significant',NULL,'PC ''are joining/is facing'' = arranged future + ongoing challenge.','medium'),
  (cid,73,225,'gap_fill','_____ (the/government) _____ (publish) _____ (the) _____ long-awaited _____ (white) _____ paper on _____ (industrial) _____ policy _____ next _____ week, _____ (follow) by _____ a _____ parliamentary _____ debate _____ (schedule/passive) for _____ (the) _____ following _____ fortnight.','The / is publishing / the / long-awaited / white / on / industrial / policy / next / followed / a / parliamentary / scheduled / the / following',NULL,'PC ''is publishing'' + ''scheduled'' (arranged) + ''is scheduled'' for government publication plan.','medium'),
  (cid,73,226,'gap_fill','_____ (the/director) _____ (step down) _____ at _____ (the) _____ end of _____ (this) _____ year after _____ fifteen _____ years _____ in _____ post — _____ (the/board) _____ (currently/conduct) _____ a _____ (succession) _____ process and _____ (hope) to _____ (announce) _____ an _____ appointment before _____ mid-year.','The / is stepping down / at / the / end / this / the / the / is currently conducting / a / succession / is hoping / announce / an / mid-year',NULL,'PC ''is stepping down/conducting/hoping'' for arranged organizational transition.','medium'),
  (cid,73,227,'gap_fill','_____ (the/summit) _____ (bring together) _____ heads of _____ (state) from _____ forty _____ countries in _____ September — _____ (the/host/government) _____ (finalize) _____ (the) _____ agenda and _____ (negotiate) _____ (the) _____ communiqué _____ text with _____ (partner) _____ governments through _____ (a/series/of) _____ (preparatory) _____ rounds.','The / is bringing together / heads / state / the / the host government / is finalizing / the / is negotiating / the / with / partner / through / a series / preparatory',NULL,'PC ''is bringing/finalizing/negotiating'' for arranged summit and preparation.','medium'),
  (cid,73,228,'multiple_choice','Which use of present continuous MOST naturally expresses a formal arranged future plan?','The Secretary-General is addressing the General Assembly next Tuesday.','[''The Secretary-General addresses the General Assembly next Tuesday.'',''The Secretary-General will be addressing the General Assembly next Tuesday.'',''The Secretary-General is addressing the General Assembly next Tuesday.'',''The Secretary-General addressed the General Assembly next Tuesday.'']','PC ''is addressing'' = scheduled/arranged future event. Present simple (addresses) would imply routine; ''will be addressing'' is less natural for arranged plans.','easy'),
  (cid,73,229,'gap_fill','_____ (the/firm) _____ (open) _____ (a) _____ new _____ regional _____ office _____ in _____ Singapore _____ in _____ March, _____ (relocate) _____ (the) _____ Asia-Pacific _____ operations _____ hub _____ from _____ Hong _____ Kong as _____ part of _____ a _____ broader _____ restructuring _____ (announce/passive) _____ last _____ quarter.','The / is opening / a / new / regional / office / in / Singapore / in / relocating / the / Asia-Pacific / operations / from / Hong Kong / a / broader / restructuring / announced / last',NULL,'PC ''is opening/relocating'' = arranged corporate restructuring plan.','medium'),

  -- BLOCK 74: PC com always/constantly (hábitos perturbadores)
  (cid,74,230,'gap_fill','_____ (the/administration) _____ (constantly/shift) _____ (its) _____ stated _____ priorities, _____ (make) _____ long-term _____ planning _____ extremely _____ difficult for _____ implementing _____ (agency) that _____ (depend) on _____ consistent _____ (direction).','The / is constantly shifting / its / stated / making / long-term / for / agencies / depend / consistent / direction',NULL,'PC + constantly = frustrating pattern; PS ''depend'' = ongoing dependency.','medium'),
  (cid,74,231,'gap_fill','_____ researchers _____ (increasingly/note) that _____ (the/committee) _____ (regularly/overrule) technical _____ recommendations for _____ political _____ reasons, _____ (undermine) _____ integrity of _____ evidence-based _____ process that _____ (supposed/be/passive) to _____ (govern) _____ decisions.','Researchers / are increasingly noting / the committee / is regularly overruling / technical / for / political / undermining / the / of / the / that / is supposed to / govern / these',NULL,'PC ''are noting/overruling/undermining'' for emerging and ongoing frustrating pattern.','hard'),
  (cid,74,232,'gap_fill','_____ (the/media) _____ (continually/frame) _____ complex _____ policy _____ issues as _____ simple _____ binary _____ choices, _____ (deprive) _____ public _____ debate of _____ (the) _____ nuance _____ (require/passive) for _____ (democratic) _____ deliberation on _____ genuinely _____ difficult _____ questions.','The / is continually framing / complex / policy / as / simple / binary / depriving / public / debate / the / nuance / required / democratic / genuinely',NULL,'PC + continually = habitual pattern; ''depriving'' = participial consequence.','medium'),
  (cid,74,233,'gap_fill','Critics _____ (observe) that _____ (the/institution) _____ (always/privilege) _____ institutional _____ self-interest over _____ stated _____ mission — a _____ pattern that _____ (erode) _____ trust among _____ (stakeholder) who _____ (look to) _____ it for _____ independent _____ leadership.','observe / the institution / is always privileging / institutional / self-interest / its / stated / a / is eroding / trust / stakeholders / look / independent',NULL,'PC + always = habitual pattern eroding trust.','medium'),
  (cid,74,234,'multiple_choice','Which sentence MOST effectively uses present continuous with ''always'' to describe a frustrating institutional pattern?','The department is always requesting additional documentation after approvals, which is causing unnecessary delays.','[''The department always requests additional documentation after approvals.'',''The department is always requesting additional documentation after approvals, which is causing unnecessary delays.'',''The department always requested additional documentation after approvals.'',''The department will always request additional documentation.'']','PC + always = annoying habitual pattern with consequence; PS ''always requests'' = neutral routine.','easy'),
  (cid,74,235,'gap_fill','Frontline _____ workers _____ (regularly/report) that _____ (the) _____ management _____ (constantly/change) _____ (the) _____ procedures _____ without _____ (consult) them — a _____ practice that _____ (not/only/reduce) _____ efficiency _____ but _____ (also/damage) _____ morale and _____ (undermine) _____ institutional _____ knowledge.','are regularly reporting / the / management / is constantly changing / the / procedures / consulting / a / that is not only reducing / but / is also damaging / morale / undermining / institutional',NULL,'PC ''are reporting/changing'' for ongoing complaint pattern about management.','hard'),
  (cid,74,236,'gap_fill','_____ funding _____ bodies _____ (increasingly/require) _____ (more) _____ compliance _____ documentation, _____ (place) _____ disproportionate _____ administrative _____ (burden) on _____ smaller _____ organizations that _____ (not/have) _____ capacity to _____ (absorb) _____ (this) without _____ (direct) _____ impact on _____ program _____ delivery.','Funding / are increasingly requiring / more / compliance / documentation / placing / disproportionate / administrative / burden / do not have / capacity / absorb / this / direct / program',NULL,'PC ''are requiring/placing'' = escalating trend frustrating smaller organizations.','hard'),
  (cid,74,237,'gap_fill','_____ (the/public) _____ (growing/realize) that _____ elected _____ officials _____ (repeatedly/make) _____ commitments they _____ (have no intention) of _____ (honor) — _____ erosion of _____ (trust) that _____ (accelerate) _____ cynicism about _____ political _____ institutions more _____ broadly.','The public / is growing increasingly aware / that / elected / are repeatedly making / have no intention / honoring / an / trust / is accelerating / cynicism / political / broadly',NULL,'PC ''is growing/making/accelerating'' for trust erosion dynamic.','hard'),

  -- BLOCK 75: PC vs PS (contraste)
  (cid,75,238,'gap_fill','While _____ standard _____ economic _____ models _____ (assume) _____ (that) _____ (agent) _____ (behave) _____ rationally, _____ (a) _____ growing _____ body of _____ behavioral _____ research _____ (demonstrate) that _____ people _____ (deviate) systematically from _____ (rational) _____ choice in _____ predictable _____ ways.','standard / economic / models / assume / that / agents / behave / a / growing / body / is demonstrating / people / deviate / rational / choice / predictable',NULL,'PS ''assume/behave/deviate'' = theoretical claims; PC ''is demonstrating'' = ongoing research challenging them.','hard'),
  (cid,75,239,'gap_fill','_____ (traditional) _____ supply _____ chains _____ (rely on) _____ (a) _____ small _____ number of _____ (high-volume) _____ supplier, but _____ many _____ companies _____ (currently/rethink) _____ this _____ model in _____ light of _____ (the) _____ vulnerabilities _____ (expose/passive) by _____ recent _____ disruptions.','Traditional / supply / chains / rely on / a / small / high-volume / suppliers / many / are currently rethinking / this / light / the / vulnerabilities / exposed / recent',NULL,'PS ''rely on'' = established practice; PC ''are rethinking'' = current reconsideration.','medium'),
  (cid,75,240,'gap_fill','Research _____ consistently _____ (show) that _____ early _____ childhood _____ (intervention) _____ (produce) _____ lasting _____ gains, yet many _____ governments _____ (still/fail) to _____ (invest) in _____ these _____ programs at _____ (the) _____ level _____ that _____ (evidence) _____ (justify).','consistently shows / early / childhood / interventions / produce / lasting / many / are still failing / invest / these / programs / the / evidence / justifies',NULL,'PS ''shows/produce/justifies'' = established findings; PC ''are failing'' = current problematic pattern.','hard'),
  (cid,75,241,'multiple_choice','Which contrast BEST illustrates the difference between present simple and present continuous?','The institution generally operates with a flat management structure, but it is currently running an experiment with team-based hierarchies.','[''The institution operates with a flat structure, but it currently runs an experiment.'',''The institution is operating with a flat structure, but it currently runs an experiment.'',''The institution generally operates with a flat management structure, but it is currently running an experiment with team-based hierarchies.'',''The institution generally operates with a flat structure, but it ran an experiment.'']','PS ''generally operates'' = permanent characteristic; PC ''is currently running'' = temporary experiment.','easy'),
  (cid,75,242,'gap_fill','_____ central _____ banks _____ (target) _____ inflation through _____ (monetary) _____ policy instruments, but _____ many _____ central _____ banks _____ (currently/grapple) with _____ (the) _____ challenge of _____ (tight) _____ labor _____ markets _____ that _____ (seem) _____ (to/resist) _____ (the) _____ traditional _____ tools.','Central / banks / target / inflation / monetary / policy / many / central / are currently grappling / the / challenge / tight / labor / markets / seem / to resist / the / traditional',NULL,'PS ''target/seem to resist'' = established behavior; PC ''are grappling'' = current challenge.','hard'),
  (cid,75,243,'gap_fill','Although _____ (the) _____ constitution _____ (guarantee) _____ freedom of _____ expression, _____ (the) _____ government _____ (currently/use) _____ defamation _____ laws _____ to _____ (intimidate) _____ journalists — _____ a _____ practice that _____ critics _____ (argue) _____ (violate) _____ spirit if _____ not _____ (the) _____ letter of _____ constitutional _____ protection.','the / constitution / guarantees / freedom / expression / the / government / is currently using / defamation / laws / intimidate / a / critics / argue / violates / the / the / constitutional',NULL,'PS ''guarantees'' = permanent constitutional status; PC ''is using'' = current abuse.','hard'),
  (cid,75,244,'gap_fill','_____ international _____ humanitarian _____ law _____ (prohibit) _____ attacks on _____ civilian _____ infrastructure, yet _____ (the/evidence) _____ (mount) that _____ (multiple) _____ parties to _____ (the) _____ conflict _____ (target) such _____ infrastructure in _____ violation of _____ (these) _____ obligations.','International / humanitarian / law / prohibits / attacks / civilian / the evidence / is mounting / multiple / the / conflict / are targeting / such / these / obligations',NULL,'PS ''prohibits'' = legal norm; PC ''is mounting/targeting'' = ongoing evidence and violations.','hard'),
  (cid,75,245,'gap_fill','_____ (the/theory) _____ (predict) that _____ (agent) _____ (defect) when _____ (the) _____ immediate _____ returns _____ (exceed) _____ long-term _____ cooperative _____ gains, yet _____ (this/field/experiment) _____ (suggest) _____ that _____ many _____ participants _____ (not/defect) even when _____ rational _____ self-interest _____ (favor) _____ doing so.','The / theory / predicts / agents / will defect / the / immediate / returns / exceed / long-term / cooperative / this field experiment / is suggesting / many / participants / are not defecting / rational / self-interest / favors',NULL,'PS ''predicts/exceed/favors'' = theoretical claims; PC ''suggesting/not defecting'' = experimental observation.','hard'),

  -- BLOCK 76: TOEFL Reading com PC
  (cid,76,246,'multiple_choice','[TOEFL Reading] ''Scientists are documenting species loss at a rate unprecedented in human history.'' What does ''are documenting'' indicate?','An ongoing process of scientific observation currently underway.','[''A completed scientific study'',''An ongoing process of scientific observation currently underway.'',''A planned future study'',''A habitual scientific practice'']','PC ''are documenting'' = ongoing current activity; would be ''have documented'' for completed study.','easy'),
  (cid,76,247,'gap_fill','[TOEFL Reading] ''_____ research _____ (suggest) that _____ (the) _____ climate _____ (warm) at _____ (a) _____ faster _____ rate than _____ (the) _____ (most/pessimistic) _____ (model) _____ (project).'' Which forms best complete the sentence?','The research / is suggesting / the / climate / is warming / a / faster / than / the / most pessimistic / models / projected',NULL,'PC ''is suggesting/warming'' = current finding in progress; PS ''projected'' = models'' earlier predictions.','medium'),
  (cid,76,248,'gap_fill','[TOEFL Reading] ''While _____ (traditional/approach) _____ (focus) on _____ (individual) _____ behavior, _____ (a) _____ new _____ generation of _____ researchers _____ (shift) attention to _____ (the) _____ systemic _____ factors _____ that _____ shape _____ individual _____ choices.'' Best forms?','traditional approaches / focus / individual / a / new / are shifting / the / systemic / factors / shape / individual',NULL,'PS ''focus/shape'' = established paradigm; PC ''are shifting'' = evolving research focus.','medium'),
  (cid,76,249,'gap_fill','[TOEFL Reading] ''_____ (the/technology) _____ (evolve) rapidly, _____ (make) _____ (the/projections) from _____ even _____ (a) _____ few years _____ ago _____ (appear) _____ obsolete.'' Best forms?','The technology / is evolving / making / projections / even / a / ago / appear',NULL,'PC ''is evolving'' + participial ''making...appear'' for rapid technological change.','medium'),
  (cid,76,250,'gap_fill','[TOEFL Reading] ''Critics _____ (argue) that _____ (the/institution) _____ (respond) to _____ symptoms rather than _____ (address) _____ root _____ causes — a _____ concern that _____ (find) _____ increasing _____ support among _____ formerly _____ sympathetic _____ observers.'' Best forms?','argue / the institution / is responding / to / rather / addressing / root / a / is finding / increasing / support / formerly / sympathetic',NULL,'PS ''argue'' = critics'' position; PC ''is responding/finding'' = ongoing inadequate response gaining critics.','hard'),
  (cid,76,251,'multiple_choice','[TOEFL Reading] ''The proportion of adults working remotely is growing across all economic sectors.'' What does this sentence describe?','An ongoing demographic/economic trend currently in progress.','[''A temporary exception to normal patterns'',''An ongoing demographic/economic trend currently in progress.'',''A completed historical shift'',''A planned policy change'']','PC ''is growing'' = ongoing trend, not a one-time event or future plan.','easy'),
  (cid,76,252,'gap_fill','[TOEFL Reading] ''_____ (the/gap) between _____ (the/highest) and _____ (the/lowest) _____ earners _____ (widen) in _____ most _____ high-income _____ countries, _____ (raise) _____ serious _____ questions about _____ (the) _____ sustainability of _____ (the) _____ current _____ model.'' Best forms?','The / gap / the highest / the lowest / earners / is widening / most / high-income / raising / serious / the / sustainability / the / current',NULL,'PC ''is widening/raising'' for inequality trend and its implications.','medium'),
  (cid,76,253,'gap_fill','[TOEFL Reading] ''While _____ (the) _____ dominant _____ paradigm _____ (treat) _____ this _____ as _____ a _____ purely _____ technical _____ question, _____ (a) _____ growing _____ body of _____ scholarship _____ (challenge) _____ that _____ framing by _____ (show) that _____ (value) _____ judgments _____ are _____ embedded in _____ (the) _____ methodology.'' Best forms?','the / dominant / paradigm / treats / as / a / purely / technical / a / growing / is challenging / that / showing / value / embedded / the / methodology',NULL,'PS ''treats'' = paradigm''s approach; PC ''is challenging'' = ongoing scholarly challenge.','hard'),

  -- BLOCK 77: TOEFL Speaking com PC
  (cid,77,254,'production','[TOEFL Speaking — 45s] A reading describes how urban demographics are changing. Summarize using present continuous.','',NULL,'The reading describes several important ways in which urban demographics are currently changing. First, cities are experiencing a significant influx of younger residents who are seeking opportunities that rural areas are not providing, and this is driving rapid urban population growth in many developing countries. At the same time, in many high-income countries, cities are ageing as baby boomers are reaching retirement age and as younger residents are finding it increasingly difficult to afford housing in major metropolitan areas, prompting some to relocate. Cities are also becoming more ethnically and culturally diverse as international migration continues, which is creating both opportunities for cultural dynamism and challenges for social cohesion that city governments are working to address. The reading notes that these demographic changes are not occurring evenly — some neighborhoods are gentrifying as higher-income residents are moving in, while others are experiencing population loss as residents are leaving in search of more affordable options. City planners are responding to these trends by reconsidering traditional approaches to housing, transportation, and service delivery, but the reading suggests that the pace of adaptation is not keeping up with the pace of change.','hard'),
  (cid,77,255,'production','[TOEFL Speaking — 45s] A professor explains what is currently happening in the global food system. Use present continuous throughout.','',NULL,'The professor explains that the global food system is currently undergoing significant stress from multiple directions simultaneously. Climate change is affecting agricultural productivity in many regions — droughts are reducing yields in historically productive areas while extreme weather events are disrupting supply chains. At the same time, global demand for food is growing as populations are increasing and as rising incomes in emerging economies are shifting diets toward more resource-intensive foods, particularly meat, which requires significantly more land and water per calorie than plant-based alternatives. In response to these pressures, the professor notes that agribusiness companies are investing heavily in precision agriculture and other technologies that are improving the efficiency of food production. Governments are reconsidering agricultural subsidies and trade policies that are distorting production incentives, and consumers are increasingly demanding transparency about how their food is produced. However, the professor argues that the pace of adaptation is not matching the pace of challenge: the food system is changing, but not as quickly as the pressures on it are intensifying, and this gap is creating increasing food insecurity in vulnerable regions.','hard'),
  (cid,77,256,'production','[TOEFL Speaking — 60s] Discuss what is happening in the global economy and what policymakers are doing in response.','',NULL,'The global economy is currently experiencing several significant transitions simultaneously, and policymakers are responding with varying degrees of urgency and effectiveness. On the demand side, consumer spending is shifting toward services as populations in high-income countries are ageing and as digital services are capturing a growing share of discretionary income. On the supply side, global value chains are reorganizing as companies are seeking to reduce the vulnerabilities that the COVID-19 pandemic exposed, with many firms reshoring or nearshoring production rather than concentrating it in the most cost-efficient single location. The energy transition is accelerating as renewable energy costs are falling dramatically and as policy is increasingly pricing carbon, creating both new investment opportunities and significant stranded asset risks in fossil fuel-intensive sectors. Labor markets are tightening in many high-income countries as populations are ageing and as the post-pandemic mismatch between skills and available jobs is persisting. Central banks are managing the difficult trade-off between fighting inflation and supporting growth in this context of multiple simultaneous shocks. Governments are increasing defense spending as geopolitical tensions are rising. Development agencies are redirecting financing toward climate adaptation as the costs of inaction are becoming increasingly apparent. The overall picture is one of a global economy that is adjusting to a fundamentally different set of conditions than those that prevailed in the pre-pandemic era, and policymakers are still working out how to manage that adjustment effectively.','hard'),
  (cid,77,257,'gap_fill','[TOEFL Speaking] According to _____ (the) _____ lecture, _____ (the) _____ institution _____ (not/simply/respond) to _____ (the) _____ changes _____ (occur) around _____ it — it _____ (actively/shape) _____ them through _____ (the) _____ choices it _____ (make) about _____ what to _____ (prioritize) and what to _____ (resist).','the / the / institution / is not simply responding / the / occurring / it / is actively shaping / the / choices / makes / prioritize / resist',NULL,'PC ''is not simply responding/shaping/occurring/makes'' for active vs reactive institutional role.','hard'),

  -- BLOCK 78: TOEFL Writing com PC
  (cid,78,258,'production','[TOEFL Writing — 200 words] Write a paragraph about current trends in higher education using present continuous.','',NULL,'Higher education is undergoing its most significant transformation in decades as multiple intersecting forces are simultaneously reshaping what universities are, what they are doing, and who they are serving. Technology is enabling new forms of learning that are removing the geographical constraints that historically defined who could access university education: students in low-income countries are increasingly enrolling in courses offered by institutions on other continents, and institutions are experimenting with hybrid models that are combining the flexibility of online learning with the social and collaborative dimensions of campus-based education. At the same time, the economic pressures on universities are intensifying as governments in many countries are reducing per-student public funding, forcing institutions to seek revenue from other sources including international student fees, private philanthropy, and commercial partnerships that are raising concerns about academic independence. The student body itself is changing as institutions are enrolling more first-generation students, more mature students, and more students who are combining work and study in ways that traditional academic calendars are not accommodating well. In response, universities are redesigning curricula to be more modular, more practically oriented, and more explicitly focused on the skills that employers and graduate schools are saying they most need. These changes are occurring at different speeds in different institutional and national contexts, but the overall direction is consistent: higher education is becoming more diverse, more digital, more global, and more responsive to market signals than it was even a generation ago.','hard'),
  (cid,78,259,'production','[TOEFL Writing — 200 words] Write a paragraph analyzing what governments are currently doing about climate change.','',NULL,'Governments around the world are responding to the climate challenge with a combination of urgency and inadequacy that reflects both the scale of the problem and the political constraints within which they are operating. Many governments are expanding their renewable energy targets and are accelerating the retirement of coal-fired power plants as the cost of clean alternatives is falling rapidly and as public pressure for climate action is growing. Several major economies are introducing carbon pricing mechanisms that are creating financial incentives for emission reduction across the economy, while others are using regulatory standards and sectoral policies to drive clean technology adoption. Governments are also significantly increasing public investment in research and development for climate technologies, particularly in areas where private investment is not yet sufficient to drive the innovation needed. At the same time, governments are falling short of the level of ambition that scientists are saying is necessary. Most are not meeting the emissions reduction targets they have set, let alone the more ambitious targets that the science is indicating are necessary to limit warming to acceptable levels. Developed-country governments are not fulfilling the climate finance commitments they are making to developing countries, limiting the ability of those countries to pursue clean development pathways. The overall picture is one of real but insufficient progress, with governments moving in the right direction but not moving nearly quickly enough given the urgency of the challenge they are facing.','hard'),
  (cid,78,260,'gap_fill','[TOEFL Writing] _____ evidence _____ (accumulate) that _____ (the/approach) _____ (not/work) as _____ intended — _____ (the/conditions) that _____ (the/intervention) _____ (try) to _____ (change) _____ (persist), while _____ (the/resources) _____ (consume/passive) at _____ (the/pace) that _____ (not/sustainable/prove).','The / is accumulating / the approach / is not working / intended / the conditions / the intervention / is trying / change / are persisting / the resources / are being consumed / a / pace / is not proving sustainable',NULL,'PC ''is accumulating/working/trying/persisting/being consumed'' for ongoing intervention failure.','hard'),
  (cid,78,261,'gap_fill','[TOEFL Writing] _____ (the/writer) _____ (argue) that _____ (the) _____ conventional _____ wisdom on _____ (this) _____ issue _____ (undergo) _____ significant _____ revision as _____ (new) _____ evidence _____ (emerge) and as _____ (the) _____ assumptions on which _____ (the/conventional) _____ (view) _____ (rest/passive) _____ (scrutiny/come under).','The / is arguing / the / conventional / wisdom / this / is undergoing / significant / revision / new / evidence / is emerging / the / which / the conventional view / is based / is coming under scrutiny',NULL,'PC ''is arguing/undergoing/emerging/coming under'' for scholarly paradigm revision.','hard'),
  (cid,78,262,'gap_fill','[TOEFL Writing] What _____ (seem) _____ (initially) _____ as _____ (a/straightforward) _____ improvement _____ (reveal) itself to be _____ considerably _____ more _____ complex as _____ (the/implementation) _____ (unfold) and as _____ (unintended) _____ consequences _____ (emerge) that _____ (planners) _____ (not/anticipate/passive).','seemed initially / a / straightforward / is revealing / considerably / more / complex / the implementation / unfolds / unintended / emerge / planners / had not anticipated',NULL,'PS ''seemed'' vs PC ''is revealing'' + ''unfolds/emerge'' for progressive revelation of complexity.','hard'),
  (cid,78,263,'gap_fill','[TOEFL Writing] The professor _____ (challenge) _____ (the) _____ reading''s _____ claim by _____ (point out) that _____ (the) _____ evidence _____ base _____ (still/develop) and that _____ (the) _____ conclusions _____ (draw/passive) from _____ it _____ (outrun) what _____ (the) _____ data _____ actually _____ (support).','is challenging / the / reading''s / pointing out / the / evidence / base / is still developing / the / conclusions / being drawn / are outrunning / the / data / actually / support',NULL,'PC ''is challenging/developing/drawing/outrunning'' for ongoing scholarly critique.','hard'),

  -- BLOCK 79: PC em contextos profissionais e de negócios
  (cid,79,264,'gap_fill','_____ (the/company) _____ (actively/explore) _____ (acquisition) _____ opportunities in _____ (the) _____ Southeast _____ Asian _____ market, _____ (focus) particularly on _____ targets that _____ (offer) _____ (the) _____ technology _____ capabilities that _____ (the) _____ firm _____ (try) to _____ (build) _____ organically.','The / is actively exploring / acquisition / opportunities / the / Southeast / Asian / focusing / offer / the / technology / the / is trying / build / organically',NULL,'PC ''is exploring/focusing/trying'' for active corporate strategy in progress.','medium'),
  (cid,79,265,'gap_fill','_____ (the/board) _____ (currently/consider) _____ a _____ significant _____ change to _____ (the) _____ executive _____ compensation _____ structure in _____ response to _____ (shareholder) _____ pressure — _____ (the/audit/committee) _____ (review) _____ (the) _____ proposals and _____ (expect) to _____ (report) _____ next _____ month.','The / board / is currently considering / a / significant / the / executive / compensation / structure / to / shareholder / the audit committee / is reviewing / the / proposals / is expected / report / next',NULL,'PC ''is considering/reviewing/is expected'' for ongoing board deliberation.','medium'),
  (cid,79,266,'gap_fill','Several _____ (major) _____ institutional _____ (investor) _____ (increasingly/demand) that _____ (portfolio) _____ companies _____ (disclose) _____ (their) _____ climate _____ exposure and _____ (develop) _____ credible _____ transition _____ plans — a _____ shift in _____ investor _____ (behavior) that _____ (fundamentally/change) _____ corporate _____ incentives.','major / institutional / investors / are increasingly demanding / portfolio / companies / disclose / their / climate / develop / credible / transition / a / shift / behavior / is fundamentally changing / corporate',NULL,'PC ''are demanding/is changing'' for investor behavior shift affecting corporate incentives.','hard'),
  (cid,79,267,'gap_fill','_____ (the/firm''s) _____ legal _____ team _____ (currently/assess) _____ potential _____ (liability) _____ arising from _____ (the) _____ recent _____ regulatory _____ changes and _____ (work) with _____ external _____ (counsel) to _____ (develop) _____ a _____ response _____ strategy.','The firm''s / is currently assessing / potential / liability / arising / the / recent / regulatory / is working / external / counsel / develop / a / response',NULL,'PC ''is assessing/working/arising'' for ongoing legal risk assessment.','medium'),
  (cid,79,268,'gap_fill','_____ (the/negotiations) _____ (well/progress) — both _____ (side) _____ (show) _____ flexibility on _____ issues where _____ (they) _____ (previously/refuse) to _____ (move), and _____ (the/atmosphere) _____ significantly _____ (improve) since _____ (the) _____ opening _____ session.','The / negotiations / are progressing well / sides / are showing / flexibility / they / had previously refused / move / the atmosphere / is significantly improving / the / opening',NULL,'PC ''are progressing/showing/improving'' for ongoing positive negotiation dynamic.','medium'),
  (cid,79,269,'multiple_choice','Which use of present continuous MOST effectively describes a business trend?','Consumers are spending an increasing proportion of their discretionary income on experiences rather than goods.','[''Consumers spend an increasing proportion of their income on experiences.'',''Consumers spent an increasing proportion of their income on experiences.'',''Consumers are spending an increasing proportion of their discretionary income on experiences rather than goods.'',''Consumers will spend an increasing proportion of their income on experiences.'']','PC ''are spending'' = ongoing evolving behavior pattern; PS ''spend'' = permanent/general habit.','easy'),
  (cid,79,270,'gap_fill','_____ organization _____ (fundamentally/rethink) _____ (the) _____ way _____ (it) _____ (deliver) _____ services as _____ digital _____ capabilities _____ (mature) and as _____ (the) _____ expectations of _____ (the) _____ populations _____ it _____ (serve) _____ (evolve).','The / is fundamentally rethinking / the / way / it / delivers / digital / capabilities / mature / the / the / populations / serves / are evolving',NULL,'PC ''is rethinking/evolving'' vs PS ''delivers/mature/serves'' for organizational digital transformation.','hard'),
  (cid,79,271,'gap_fill','_____ (the/workforce) _____ (age) and _____ (skill) _____ gaps _____ (widen) — both _____ (factor) that _____ (drive) _____ (the) _____ firm''s _____ decision to _____ (invest) _____ significantly in _____ training and _____ retention rather than _____ (rely) _____ solely on _____ external _____ recruitment.','The / is ageing / skill / gaps / are widening / both / factors / are driving / the / firm''s / to / invest / significantly / rather / relying / solely / external',NULL,'PC ''is ageing/widening/driving'' for workforce dynamics driving investment decision.','hard'),

  -- BLOCK 80: PC para tendências e desenvolvimentos globais
  (cid,80,272,'gap_fill','_____ (the/balance) of _____ global _____ economic _____ power _____ (shift) eastward as _____ (large) _____ Asian _____ economies _____ (grow) at _____ rates that _____ systematically _____ (outpace) _____ (the) _____ high-income _____ West — a _____ rebalancing that _____ (reshape) _____ trade _____ flows, _____ investment _____ patterns, and _____ geopolitical _____ alignments.','The / balance / global / economic / power / is shifting / large / are growing / outpace / the / high-income / a / is reshaping / trade / investment / geopolitical',NULL,'PC ''is shifting/growing/reshaping'' for ongoing global economic rebalancing.','medium'),
  (cid,80,273,'gap_fill','_____ (digital/the) _____ transformation _____ of _____ (the) _____ financial _____ sector _____ (accelerate) as _____ fintech _____ companies _____ (disrupt) _____ traditional _____ banking _____ models and as _____ central _____ banks _____ (explore) _____ (the) _____ potential of _____ digital _____ currencies.','The / digital / transformation / of / the / financial / sector / is accelerating / fintech / are disrupting / traditional / banking / central / banks / are exploring / the / potential / digital',NULL,'PC ''is accelerating/disrupting/exploring'' for financial sector transformation.','medium'),
  (cid,80,274,'gap_fill','_____ (the/geopolitical) _____ competition _____ between _____ major _____ powers _____ (intensify) across _____ multiple _____ domains — _____ (not/only) _____ in _____ traditional _____ military _____ dimensions but _____ in _____ technology, _____ trade, _____ diplomacy, and _____ (the) _____ contest for _____ global _____ influence.','The / geopolitical / competition / between / major / powers / is intensifying / multiple / not only / in / traditional / military / but / in / technology / trade / diplomacy / the / contest / global',NULL,'PC ''is intensifying'' for expanding domain of great power competition.','hard'),
  (cid,80,275,'gap_fill','_____ (the/proportion) of _____ (the) _____ global _____ population _____ (live) in _____ extreme _____ poverty _____ (decline) over _____ (the) _____ long _____ term, but _____ progress _____ (slow) in _____ recent _____ years as _____ (the) _____ effects of _____ conflict, _____ climate _____ change, and _____ pandemic _____ (reverse) _____ earlier _____ gains.','The / proportion / the / global / population / living / extreme / poverty / is declining / the / long / term / is slowing / recent / the / effects / climate / change / and / pandemic / are reversing / earlier',NULL,'PC ''is declining/slowing/reversing'' for complex poverty trend with divergent sub-dynamics.','hard'),
  (cid,80,276,'multiple_choice','Which sentence MOST effectively uses present continuous to describe a global development?','Multilateral institutions are losing credibility as major powers are increasingly bypassing them in favor of bilateral arrangements.','[''Multilateral institutions lose credibility as major powers increasingly bypass them.'',''Multilateral institutions are losing credibility as major powers are increasingly bypassing them in favor of bilateral arrangements.'',''Multilateral institutions have lost credibility as major powers have bypassed them.'',''Multilateral institutions will lose credibility as major powers will bypass them.'']','PC ''are losing/bypassing'' = both trends ongoing simultaneously; PS would imply permanent state.','easy'),
  (cid,80,277,'gap_fill','_____ (the/platform) _____ economy _____ (grow) rapidly in _____ both _____ (the) _____ developed and _____ developing _____ world, _____ (create) _____ (new) _____ forms of _____ work that _____ (not/easily/fit) _____ (the) _____ regulatory _____ frameworks _____ that _____ (traditionally) _____ (govern) _____ employment _____ relationships.','The / platform / economy / is growing / rapidly / the / developed / creating / new / forms / work / do not easily fit / the / regulatory / frameworks / that / traditionally / govern / employment',NULL,'PC ''is growing/creating'' vs PS ''do not fit/govern'' for platform economy disruption.','medium'),
  (cid,80,278,'gap_fill','_____ (the) _____ rapid _____ advancement of _____ artificial _____ intelligence _____ (raise) _____ fundamental _____ questions about _____ (the) _____ future of _____ work, _____ (the) _____ distribution of _____ economic _____ gains, and _____ (the) _____ governance _____ frameworks _____ (need/passive) to _____ (ensure) _____ that _____ (the) _____ technology _____ (deploy/passive) _____ (responsibly).','The / rapid / advancement / is raising / fundamental / the / future / the / distribution / economic / the / governance / frameworks / needed / ensure / the / technology / is deployed / responsibly',NULL,'PC ''is raising'' + ''needed/deployed'' (passive) for AI advancement implications.','hard'),
  (cid,80,279,'gap_fill','_____ (the/climate) _____ crisis _____ (force) _____ communities around _____ (the) _____ world to _____ (confront) _____ (the) _____ limits of _____ (the) _____ development _____ models that _____ (serve) them, _____ (prompt) _____ (a) _____ broader _____ rethinking of _____ what _____ (sustainable) _____ prosperity _____ actually _____ (mean).','The / climate / is forcing / communities / the / confront / the / limits / the / development / models / have served / prompting / a / broader / rethinking / sustainable / actually means',NULL,'PC ''is forcing/prompting'' for climate crisis driving fundamental rethinking.','hard'),

  -- BLOCK 81: Gap fill avançado
  (cid,81,280,'gap_fill','While _____ (earlier) _____ generations of _____ economists _____ (treat) _____ inequality primarily as _____ (a/distributional) _____ concern, _____ (a/growing) _____ consensus _____ (emerge) that _____ high _____ (level) of _____ inequality _____ (undermine) _____ economic _____ efficiency _____ itself — a _____ shift that _____ (reshape) _____ policy _____ prescriptions _____ significantly.','earlier / generations / economists / treated / a / distributional / a growing / is emerging / high / levels / undermine / economic / a / is reshaping / policy / significantly',NULL,'PS ''treated/undermine'' vs PC ''is emerging/reshaping'' for evolving economics consensus.','hard'),
  (cid,81,281,'gap_fill','_____ (the) _____ scientific _____ community _____ (grapple) with _____ (the) _____ implications of _____ findings that _____ (challenge) _____ long-held _____ assumptions — not _____ (because) _____ (the) _____ evidence _____ (ambiguous/be) but _____ (because) _____ (the) _____ institutional and _____ political _____ (consequence) of _____ (accept) _____ them _____ (prove) _____ significant.','The / scientific / community / is grappling / the / implications / challenge / long-held / assumptions / because / the / evidence / is ambiguous / because / the / institutional / political / consequences / accepting / are proving / significant',NULL,'PC ''is grappling/proving'' for ongoing difficulty accepting implications of clear evidence.','hard'),
  (cid,81,282,'gap_fill','_____ (the/governance) _____ frameworks that _____ (govern) _____ (the) _____ internet _____ (develop/passive) incrementally and _____ (now/adapt/passive/not) _____ to _____ (address) _____ (the) _____ challenges _____ (pose/passive) by _____ (the) _____ current _____ scale and _____ centralization of _____ digital _____ power.','The / governance / frameworks / govern / the / were developed / are now not adapting / to / address / the / challenges / posed / the / current / scale / centralization / digital',NULL,'PS ''govern/were developed'' = established but outdated; PC ''not adapting'' = failure to evolve.','hard'),
  (cid,81,283,'gap_fill','_____ national _____ (identity) _____ (fluid/prove) as _____ (the) _____ demographic _____ composition of _____ (society) _____ (change) and as _____ contested _____ narratives about _____ (the) _____ past and _____ future _____ (compete) for _____ cultural _____ dominance — a _____ contest that _____ (play out) in _____ (politics), _____ culture, and _____ (every) _____ day _____ (life).','National / identities / are proving fluid / the / demographic / composition / societies / is changing / contested / narratives / are competing / cultural / dominance / a / is playing out / politics / everyday',NULL,'PC ''are proving/changing/competing/playing out'' for identity fluidity dynamics.','hard'),
  (cid,81,284,'gap_fill','_____ (the/relationship) between _____ (the) _____ state and _____ (the) _____ market _____ (renegotiate/passive) in _____ many _____ contexts as _____ (the) _____ limitations of _____ both _____ pure _____ marketization and _____ (statism) _____ (become) _____ apparent — _____ (a) _____ hybrid _____ approaches _____ (emerge) that _____ (not/fit) _____ easily _____ into _____ existing _____ ideological _____ categories.','The / relationship / between / the / state / and / the / market / is being renegotiated / the / limitations / both / pure / statism / are becoming / apparent / hybrid / are emerging / do not fit / existing / ideological',NULL,'PC ''is being renegotiated/emerging/becoming'' for ideological pragmatic shift.','hard'),
  (cid,81,285,'gap_fill','As _____ (the) _____ boundaries _____ between _____ (the) _____ public and _____ private _____ sectors _____ (blur), _____ (new) _____ forms of _____ governance _____ (emerge) that _____ (not/easily/classify) as _____ either — _____ (phenomenon) that _____ (challenge) _____ (the) _____ conventional _____ analytical _____ categories that _____ scholars _____ (use) to _____ (study) them.','the / boundaries / between / the / public / private / sectors / are blurring / new / forms / governance / are emerging / do not classify easily / a / phenomenon / is challenging / the / conventional / analytical / scholars / use / to study',NULL,'PC ''blurring/emerging/challenging'' for governance category evolution.','hard'),
  (cid,81,286,'gap_fill','_____ (the/world) _____ (not/simply/change) — it _____ (transform) in _____ ways that _____ (require) _____ (those) _____ responsible for _____ (governance) at every _____ level to _____ (rethink) _____ (their) _____ assumptions, _____ (their) _____ institutions, and _____ ultimately _____ (their) _____ understanding of _____ what _____ effective _____ leadership _____ (look like) in _____ circumstances _____ (this) _____ novel.','The / world / is not simply changing / is transforming / ways / require / those / responsible / governance / to / rethink / their / assumptions / their / institutions / ultimately / their / understanding / effective / leadership / looks like / circumstances / this / novel',NULL,'PC ''is not simply changing/transforming/require'' for transformative vs incremental change argument.','hard'),
  (cid,81,287,'gap_fill','_____ (many) _____ of _____ (the) _____ most _____ important _____ changes _____ (occur) not _____ with _____ fanfare but _____ quietly, _____ incrementally, _____ and _____ (often) _____ below _____ (the) _____ threshold of _____ public _____ awareness — _____ (this) is _____ (part) of _____ what _____ (make) _____ them so _____ (difficult) to _____ respond to _____ effectively.','Many / of / the / most / important / changes / are occurring / not / with / fanfare / quietly / incrementally / often / below / the / threshold / public / awareness / this / part / what makes / them / difficult / respond / effectively',NULL,'PC ''are occurring'' for quiet incremental change below awareness threshold.','medium'),

  -- BLOCK 82: Exercícios finais de produção
  (cid,82,288,'production','[TOEFL Writing — 200 words] Write a concluding paragraph on what present trends indicate about the future, using present continuous throughout.','',NULL,'The trends that are currently shaping the global landscape are pointing in directions that will require significant adaptation from individuals, institutions, and governments alike. Technology is transforming the nature of work at a pace that formal education systems are not keeping up with, creating a growing skills gap that is affecting both individual economic security and national economic competitiveness. The climate is changing in ways that are already imposing costs on vulnerable populations and that are accelerating toward thresholds beyond which adaptation will become increasingly difficult and expensive. Geopolitical competition is intensifying in ways that are making the multilateral cooperation needed to address shared challenges more difficult to sustain. At the same time, more hopeful trends are also unfolding: clean energy costs are falling rapidly, making the energy transition increasingly economically rational; digital technology is enabling new forms of access to education, health information, and financial services that are reaching populations that traditional systems were not serving; and civil society organizations are mobilizing at scale to address the gaps that governments and markets are leaving. The picture that is emerging from these converging trends is not one of inevitable decline or inevitable progress but of a genuinely open contest between forces that are pushing in different directions — and the outcome will depend significantly on the choices that individuals, institutions, and governments are making right now.','hard'),
  (cid,82,289,'production','[TOEFL Speaking — 60s] The reading describes several changes that are occurring in democratic systems. Summarize and the professor''s response.','',NULL,'The reading describes several troubling changes that are currently occurring in democratic systems around the world. Civic participation is declining in many established democracies as trust in institutions is eroding and as citizens are becoming increasingly cynical about whether their participation makes a difference. At the same time, populist movements are growing in many countries, offering simple narratives that are appealing to voters who feel that mainstream parties are not addressing their concerns. Social media is transforming the information environment in ways that are making it more difficult for citizens to distinguish reliable information from misinformation, and platforms are amplifying emotionally resonant content in ways that are contributing to polarization. Independent institutions — courts, central banks, oversight agencies — are coming under pressure from governments that are seeking to reduce constraints on executive power. The professor responds by arguing that while these trends are real and concerning, democratic systems are also showing resilience in ways that the reading underestimates. Civil society organizations are mobilizing to defend democratic norms, and citizens who had been disengaged are returning to political participation when they perceive democracy itself to be at risk. Courts are successfully resisting executive overreach in many contexts. The professor concludes that democracy is under stress but is also generating the responses needed to defend it, and that the outcome of this contest is genuinely uncertain rather than predetermined in either direction.','hard'),
  (cid,82,290,'gap_fill','[TOEFL Writing] What _____ (the/data) _____ (show) is _____ both _____ (encouraging) and _____ (concerning): _____ (the) _____ right _____ indicators _____ (improve), but _____ (not/at) _____ (the) _____ pace _____ (require/passive) and _____ (not) _____ in _____ (the) _____ context that _____ (need) to _____ (sustain) _____ (the) _____ progress _____ (achieve/passive) so _____ far.','the data / is showing / both / encouraging / concerning / the / right / indicators / are improving / not at / the / pace / required / not / the / context / is needed / sustain / the / progress / achieved / far',NULL,'PC ''is showing/improving/needed'' + PS ''required/achieved'' for nuanced progress assessment.','hard'),
  (cid,82,291,'gap_fill','In _____ (the) _____ meantime, _____ (the/world) _____ (not/wait): _____ (the) _____ challenges _____ (intensify), _____ (the) _____ window for _____ effective _____ action _____ (narrow), and _____ (the) _____ costs of _____ inaction _____ (rise) even as _____ (the) _____ debate about _____ what _____ to _____ (do) _____ (continue).','the / meantime / the world / is not waiting / the / challenges / are intensifying / the / window / is narrowing / the / costs / are rising / the / debate / continues',NULL,'PC ''is not waiting/intensifying/narrowing/rising'' + PS ''continues'' for urgency argument.','hard'),
  (cid,82,292,'gap_fill','_____ (the/analysis) _____ (point) clearly in _____ one _____ direction, even if _____ (the) _____ conclusions _____ (sit) uncomfortably with _____ (the) _____ prevailing _____ (wisdom) and even if _____ (the) _____ institutional _____ interests _____ (resist) them.','The / analysis / is pointing / one / direction / the / conclusions / sit / the / prevailing / wisdom / the / institutional / interests / are resisting',NULL,'PC ''is pointing/resisting'' vs PS ''sit'' for evidence clarity despite institutional resistance.','hard'),
  (cid,82,293,'production','[TOEFL Writing — Final capstone 200 words] Write a conclusion on what current trends are revealing about the nature of the challenge.','',NULL,'The trends that this analysis has examined are collectively revealing something important about the nature of the challenge the international community is currently facing: it is not primarily a technical challenge, in the sense that the solutions are mostly known, but a political and institutional challenge, in the sense that the barriers to implementing those solutions are rooted in the distribution of power, interests, and ideas rather than in the absence of knowledge about what needs to be done. This distinction matters because it shapes what kinds of interventions are most likely to be effective. If the challenge were primarily technical, the right response would be to invest in research and innovation. But because it is primarily political and institutional, the right response is to invest in changing the conditions — the incentive structures, the accountability mechanisms, the narratives, and the power relations — that are currently preventing known solutions from being implemented. The evidence that is emerging from across the case studies this analysis has examined is consistently pointing in this direction: the countries and organizations that are making progress are doing so not primarily because they have discovered new solutions but because they are creating the political and institutional conditions that allow existing solutions to be implemented. This is both a more difficult and a more hopeful finding than it might initially appear: more difficult because political and institutional change is genuinely hard, but more hopeful because it means the knowledge of what to do is not the binding constraint.','hard'),
  (cid,82,294,'gap_fill','_____ (the/trends) _____ (examine) in _____ (this) _____ analysis _____ (paint) _____ (a) _____ complex _____ picture — one in which _____ (the) _____ forces of _____ progress and _____ regression _____ (operate) simultaneously and in which _____ (the) _____ outcome _____ (not/determine/passive) by _____ any _____ single _____ factor but by _____ (the) _____ interaction of _____ many.','The / trends / examined / this / are painting / a / complex / picture / the / forces / progress / regression / are operating / simultaneously / the / outcome / is not determined / any / single / by / the / interaction / many',NULL,'PC ''are painting/operating'' for complex ongoing trend assessment.','medium'),
  (cid,82,295,'gap_fill','If _____ (we) _____ (heed) _____ (the) _____ signals that _____ (the) _____ evidence _____ (send), _____ (we) _____ (have) _____ everything _____ (we) _____ need to _____ (act) — _____ question is whether _____ (the) _____ political _____ will to _____ (do) so _____ (materialize) in _____ time.','we / heed / the / the / evidence / is sending / we / will have / everything / we / need / act / the / question / the / political / will / to do / materializes / in / time',NULL,'PC ''is sending'' + conditional Type 1 ''heed/will have'' for political will argument.','hard'),
  (cid,82,296,'gap_fill','_____ (the) _____ world _____ (at) _____ (a) _____ crossroads, and _____ (the) _____ choices _____ (make/passive) in _____ (the) _____ coming _____ decade _____ (shape) _____ (the) _____ trajectory for _____ generations _____ to _____ come — _____ (this) is _____ (the) _____ scale of _____ (the) _____ moment in _____ which _____ (we) _____ (live).','The / world / is at / a / crossroads / the / choices / being made / the / coming / decade / will shape / the / trajectory / generations / this / the / scale / the / moment / which / we / are living',NULL,'PC ''is at/being made/are living'' for present historical moment framing.','medium'),
  (cid,82,297,'gap_fill','_____ (the) _____ question is _____ not _____ whether _____ change _____ (come) — it _____ (already/come) — but _____ whether _____ (the) _____ institutions _____ and _____ leaders _____ (charge/passive) with _____ (govern) it _____ (rise) to _____ (the) _____ challenge _____ (present) by _____ (the) _____ moment.','The / question / not / whether / change / is coming / is already coming / the / institutions / leaders / charged / governing / will rise / the / challenge / presented / the / moment',NULL,'PC ''is coming/is already coming/charged/governing'' + future for institutional challenge framing.','hard'),
  (cid,82,298,'production','[TOEFL Speaking — 45s] What are the most significant changes currently occurring in the field discussed in the reading? Use present continuous throughout.','',NULL,'The field is currently experiencing several significant changes that are collectively transforming its fundamental assumptions and practices. The traditional models that have governed the field for decades are giving way to new approaches as the evidence base is expanding and as the limitations of conventional methods are becoming increasingly apparent. Practitioners are adopting new tools and techniques that are enabling them to work more effectively in contexts where traditional approaches were not adequate. Researchers are challenging long-held assumptions and are producing findings that are requiring fundamental revisions to the theoretical frameworks that have guided the field. At the same time, the boundary between this field and related disciplines is blurring as complex real-world challenges are requiring integrative approaches that draw on multiple bodies of knowledge. The training and professional development systems that prepare people to work in the field are also changing, though perhaps not as quickly as the field itself is evolving, creating a gap between the skills that practitioners are developing through formal training and the skills that current practice is demanding. Overall, the field is in a period of productive ferment — one in which old certainties are giving way to new possibilities, even if the direction of travel is not yet fully clear.','hard'),
  (cid,82,299,'production','[TOEFL Writing — 200 words] Write a body paragraph on what is happening to civic participation in democracies.','',NULL,'Civic participation in established democracies is undergoing a complex transformation that is defying simple characterization as either decline or renewal. Traditional forms of participation — voting in elections, joining political parties, engaging with formal representative institutions — are declining in many contexts as citizens are becoming increasingly skeptical about whether these channels of influence are actually effective. Trust in political parties, parliaments, and politicians is falling across most established democracies, and this declining trust is suppressing the motivation to engage through conventional channels. At the same time, other forms of civic engagement are growing: protest movements are mobilizing millions of people who are choosing direct action over electoral participation; civil society organizations are expanding their membership and their activities in response to what their members are perceiving as failures of representative government; and digital platforms are enabling new forms of collective action that are bypassing traditional organizational structures. The nature of political identity itself is shifting as traditional class-based and ideological alignments are breaking down and as new cultural and values-based identities are organizing political behavior in ways that existing party systems are struggling to accommodate. What is emerging is not the death of civic participation but its transformation into forms that existing democratic institutions are finding difficult to process and incorporate — a challenge that is putting those institutions under stress precisely at a time when effective collective decision-making is most urgently needed.','hard'),
  (cid,82,300,'production','[TOEFL Writing — Final capstone 200 words] Write a conclusion synthesizing what current trends are revealing about governance challenges.','',NULL,'The analysis of current trends that this essay has undertaken reveals that the governance challenges facing political systems at every level are intensifying precisely at a moment when the institutional capacity to address them is under particular stress. Democratic systems are grappling with declining trust, rising polarization, and the disruptive effects of digital technology on the information environment that democratic deliberation requires, at the same time as the problems they are being asked to address — climate change, economic inequality, technological disruption, geopolitical competition — are increasing in scale and complexity. International institutions are struggling to maintain relevance as the major powers that created them are pursuing narrower national interests, undermining the collective action capacity that global challenges require. Sub-national governments are inheriting functions that higher levels of government are failing to perform, without necessarily receiving the resources or authority needed to perform them effectively. What is emerging from this conjuncture is not necessarily democratic collapse — democratic systems have survived severe stress before — but a genuine risk that the governance institutions through which collective choices are made will prove inadequate to the scale of the choices that current trends are demanding. Addressing this risk requires not abandoning democratic governance but strengthening it: building the institutional capacity, restoring the trust, and developing the deliberative processes through which democratic systems can make and implement the difficult choices that the current moment is requiring of them.','hard')

